    "docs/how-to/billing-and-invoices.md": {
      "feature": "Billing and invoices",
      "route": "/hub/settings?tab=billing",
      "summary": "Settings › Billing shows everything you pay CDS for on one screen: your plan, your next bill, your card, each item on your one monthly subscription, your Care…",
      "activate": [
        {
          "screen": "`/hub/settings?tab=billing`",
          "action": "Before you have paid, open Settings, then the Billing tab",
          "expected": "A blue strip reads \"You haven't checked out yet. Your plan and invoices show here after you pay.\" with a **Go to checkout** button; under it \"Your plan, card and invoices show here after checkout.\", Quotes from CDS, and Invoices with \"No invoices yet\""
        },
        {
          "screen": "`/hub/checkout`",
          "action": "Click **Go to checkout**, then pay for your site (see the Checkout how-to)",
          "expected": "You come back to the hub; the payment is confirmed"
        },
        {
          "screen": "`/hub/settings?tab=billing`",
          "action": "Open Settings › Billing again",
          "expected": "A green strip reads \"You're all paid up. Next bill {date}, {amount}.\" and the Your plan, What you pay for, Care Plan, Media storage, Quotes from CDS and Invoices sections show"
        }
      ],
      "use": [
        {
          "screen": "Settings › Billing, Your plan",
          "action": "Read the Plan, Next bill and Card rows",
          "expected": "Plan reads e.g. \"Standard website, billed monthly\"; Next bill reads e.g. \"8 Nov 2026 · $39.00 plus sales tax\"; Card reads e.g. \"Visa ending 4242, expires 08/28\". To switch between monthly and yearly, ask CDS Support (the line under the plan says so)"
        },
        {
          "screen": "Settings › Billing, What you pay for",
          "action": "Read the list",
          "expected": "One row per item with its price: your plan, each add-on (\"$9/mo\" or \"Included\"), storage packs (\"+5 GB storage × 1 · $5/mo\"), build payments (\"Website build, payment 3 of 6 · $250/mo\" with \"Ends after {date}.\"), and the Care Plan when on. The last row reads \"Monthly total · {amount} plus sales tax\". Each amount is what you are billed for that item: with a price lock, your locked price, not today's list price. An item whose price CDS has not set yet reads \"Price coming soon\". **Manage add-ons** opens Get add-ons"
        },
        {
          "screen": "Settings › Billing, Your plan",
          "action": "Click **Update card**",
          "expected": "The secure card page opens in the same tab (in test mode, the CDS test card page)"
        },
        {
          "screen": "The card page",
          "action": "Enter the new card and save, then follow the link back",
          "expected": "You land on Settings › Billing and a toast reads \"Card updated.\""
        },
        {
          "screen": "Settings › Billing, Invoices",
          "action": "Find the invoice you want (newest first; **Show more** loads older ones) and click **View invoice**",
          "expected": "The invoice page opens (Stripe's opens in a new tab), with its PDF to download for your records. Each row shows the date, invoice number, what it was for, the amount with its tax, and a badge: Paid, Due, Unpaid, Refunded or Cancelled"
        },
        {
          "screen": "Settings › Billing",
          "action": "If a card payment fails, read the yellow strip",
          "expected": "It reads \"Your last payment of {amount} didn't go through. Your site and add-ons are still on while Stripe tries again. Update your card to fix it now.\" with a primary **Update card** button. The tab label reads \"Billing · 1\""
        },
        {
          "screen": "Settings › Billing",
          "action": "If payment stopped after the retries, read the yellow strip",
          "expected": "It reads \"Your add-ons are paused because payment stopped. Your site's pages are still live and nothing was deleted. Pay {amount} to turn everything back on.\" In What you pay for, each paused add-on carries a **Paused** badge. Nothing new can be added while paused"
        },
        {
          "screen": "Settings › Billing, strip",
          "action": "Click **Update card and pay**, save a working card on the card page and pay the open invoice",
          "expected": "You come back to Settings › Billing; the strip turns green and your paused add-ons come back on with everything they held"
        },
        {
          "screen": "Settings › Billing, Quotes from CDS",
          "action": "When CDS sends you a quote, click **Review quote**",
          "expected": "The quote page opens; quotes waiting for you sit first, with a \"Waiting for you\" badge, and the strip shows \"CDS sent you a quote: {title}.\""
        },
        {
          "screen": "Any hub screen except Settings › Billing",
          "action": "While a card payment has failed, look at the top of the page",
          "expected": "A yellow banner reads \"Your last card payment didn't go through. Update your card to keep your add-ons on.\" with an **Update card** button. It has no close button and only the owner sees it"
        },
        {
          "screen": "Any hub screen except Settings › Billing",
          "action": "While add-ons are paused, look at the top of the page",
          "expected": "The yellow banner (pause icon) reads \"Your add-ons are paused because payment stopped. Your site's pages are still live and nothing was deleted. Pay {amount} to turn everything back on.\" with **Update card and pay**"
        },
        {
          "screen": "`/hub/website?tab=testimonials` (a bookmark of a paused add-on's tab)",
          "action": "Open the bookmark while paused",
          "expected": "You land on Pages with \"Testimonials is paused because payment stopped. Pay from Settings › Billing to see your testimonials again.\" (the owner also gets **Update card and pay**)"
        },
        {
          "screen": "Page builder, block list",
          "action": "Open a page that holds a paused add-on's block",
          "expected": "The block keeps its place, dimmed, with a **Paused** badge and \"Testimonials is paused, so this block doesn't show on your site. It comes back when payment does.\""
        },
        {
          "screen": "Any hub screen",
          "action": "After paying, open the hub",
          "expected": "The banner is gone and a toast reads \"Payment received. Your add-ons are back on.\" once; reloading does not show it again"
        }
      ]
    },
