    "docs/how-to/content-notices-and-suspension.md": {
      "feature": "Content notices and suspension",
      "route": "/hub/today",
      "summary": "Every site CDS hosts follows the same hosting rules.",
      "activate": [
        {
          "screen": "`/hub/profile`",
          "action": "Check that your email address is current",
          "expected": "Notice, suspension and report emails reach you (Owner and Admins)"
        }
      ],
      "use": [
        {
          "screen": "Your email inbox",
          "action": "Open \"Action needed on Rivera Bakery by Thu 16 Oct\"",
          "expected": "\"CDS found something on your site that breaks the hosting rules. Fix it by Thu 16 Oct or your site goes offline.\", then what to change, then \"If you think this is a mistake, reply in CDS Support.\" and a **See what to fix** button"
        },
        {
          "screen": "Any hub page, for example `/hub/today`",
          "action": "Read the strip under the top bar",
          "expected": "The same sentence with the date in bold (\"Thu 16 Oct, 5:00 pm\") and a **See what to fix** link"
        },
        {
          "screen": "Strip",
          "action": "Click **See what to fix**",
          "expected": "`/hub/support?tab=messages` opens on CDS's note, which says exactly what to change and where"
        },
        {
          "screen": "The page or file named in the note",
          "action": "Change or remove it in the page builder or the media library, then publish",
          "expected": "The live site no longer shows it"
        },
        {
          "screen": "`/hub/support?tab=messages`",
          "action": "Reply to CDS's note that it's fixed (or click **Get help** to ask a question)",
          "expected": "CDS checks the site and marks it fixed. The strip goes away"
        },
        {
          "screen": "Your email inbox, notice not fixed in time (or a serious case)",
          "action": "Open \"Rivera Bakery is offline\"",
          "expected": "\"Your site is offline. CDS suspended it on 16 Oct. Your hub and CDS Support still work.\" with the reason and an **Open CDS Support** button"
        },
        {
          "screen": "Any hub page",
          "action": "Read the red strip under the top bar",
          "expected": "\"Your site is offline. CDS suspended it on 16 Oct. Your hub and CDS Support still work.\" with a **Read why** link to the CDS note in Messages"
        },
        {
          "screen": "Your site's address, in a private window",
          "action": "Open any page",
          "expected": "A plain page \"This site is temporarily unavailable.\" and \"Please check back later.\" No branding, no reason, nothing from your site. Search engines are told not to index it"
        },
        {
          "screen": "`/hub/support?tab=messages`",
          "action": "Fix what the note names and reply to CDS",
          "expected": "CDS reviews it and lifts the suspension"
        },
        {
          "screen": "Your email inbox",
          "action": "Open \"Rivera Bakery is back online\"",
          "expected": "\"Your site is back online. Thanks for sorting it out.\" and **Open your hub**. Every page, file, add-on and setting is exactly as it was before the suspension"
        },
        {
          "screen": "Your email inbox, after a visitor reported a page",
          "action": "Open \"A page on Rivera Bakery was reported\"",
          "expected": "\"Someone reported a page on Rivera Bakery to CDS. CDS reviews every report, usually within 2 business days, and tells you if anything needs to change.\" with **Page** (its address) and **Reason** (Copyright, Scam or fraud, Illegal content or Something else). You don't need to do anything unless CDS asks"
        }
      ]
    },
    "docs/how-to/cookie-consent.md": {
      "feature": "Cookie notice and click-to-load media",
      "route": "/hub/website?tab=pages",
      "summary": "One consent rule for everything your site loads from other companies: videos from YouTube or Vimeo, Spotify and other audio players, Calendly and Google…",
      "activate": [
        {
          "screen": "`/hub/website?tab=pages`",
          "action": "Click a page name, for example **Home**",
          "expected": "The page builder opens at `/hub/website/pages/[pageId]`"
        },
        {
          "screen": "`/hub/website/pages/[pageId]`",
          "action": "In a Columns block, click **Add item**, choose **Video**, paste a YouTube link into the link field, fill **Title** (for example \"Spring menu tour\") and click **Save item**",
          "expected": "The video item is listed in the column. (Adding a **Map** block works the same way.)"
        },
        {
          "screen": "`/hub/website/pages/[pageId]`",
          "action": "Click **Publish changes**",
          "expected": "The page is published. Nothing else to switch on: the site now shows the cookie notice to new visitors. A site with no video links, audio links, booking calendars or maps never shows it"
        }
      ],
      "use": [
        {
          "screen": "Published page, first visit",
          "action": "Open the page",
          "expected": "The cookie notice sits at the bottom of the screen: \"This site uses cookies for embedded videos from other companies. Choose what to allow.\" with **Accept all** and **Only necessary**, both the same size and style. The page above still works"
        },
        {
          "screen": "Published page, the video",
          "action": "Look at the video",
          "expected": "It shows its cover picture (or a plain panel) with a round play button, and under it \"Plays from YouTube, which may set cookies.\" Nothing has loaded from YouTube yet"
        },
        {
          "screen": "Published page, the video",
          "action": "Click the play button",
          "expected": "That video loads in the same space and focus moves into it. Other videos and maps on the page stay as placeholders. The cookie notice stays until a choice is made"
        },
        {
          "screen": "Cookie notice",
          "action": "Click **Accept all**",
          "expected": "The notice fades away, every video and map on the page loads at once, and on later visits (for 180 days) they load without a click and no notice shows"
        },
        {
          "screen": "Cookie notice",
          "action": "Click **Only necessary** instead",
          "expected": "The notice fades away and every video and map stays a placeholder; each one still loads with its own click"
        },
        {
          "screen": "Published page with an automatic pop-up",
          "action": "Open the page on a computer",
          "expected": "The pop-up waits until the cookie notice is answered, then appears (its delay counts from the choice)"
        },
        {
          "screen": "Published page on a phone (narrower than 768 px)",
          "action": "Open the page",
          "expected": "No automatic pop-up appears. A button set to open the pop-up still opens it"
        },
        {
          "screen": "Pop-up with an uploaded video",
          "action": "Open the pop-up, then close it",
          "expected": "The video starts playing muted when the pop-up opens and stops when it closes. A YouTube or Vimeo video in a pop-up never plays on its own and stops when the pop-up closes"
        },
        {
          "screen": "Site footer",
          "action": "Click **Cookie choices** (the footer arrives with plan 07-25)",
          "expected": "The cookie notice appears again; a new choice replaces the old one"
        }
      ]
    },
