    "docs/how-to/leaving-cds.md": {
      "feature": "Leaving CDS",
      "route": "/hub/leaving",
      "summary": "Leaving CDS gives 30 days' notice.",
      "activate": [
        {
          "screen": "Settings › Billing (`/hub/settings?tab=billing`), signed in as the **Owner**",
          "action": "On the last row **Leave CDS**, click **Leave CDS…**",
          "expected": "**Leaving CDS** (`/hub/leaving`) opens: \"We're sorry to see you go. Here's exactly what happens, in order.\" and the ordered list (DNS first, site up 30 days, download, billing, site closes)"
        },
        {
          "screen": "The same row while CDS staff view your site",
          "action": "Read the row",
          "expected": "The button is off: \"You're viewing as CDS staff, so this is turned off. Only the owner can start leaving. Staff use the console.\""
        }
      ],
      "use": [
        {
          "screen": "`/hub/leaving`",
          "action": "Optionally pick **Why are you leaving? (optional)** and write **Anything we should know? (optional)**",
          "expected": "The fields are filled"
        },
        {
          "screen": "The same page",
          "action": "Enter the code from the email (\"To confirm, we emailed a code to m•••@gmail.com.\") and click **Start the 30-day notice**",
          "expected": "The button shows **Starting…**, then a toast reads \"Your 30-day notice has started. Next: move your DNS.\" Every hub screen shows \"Leaving CDS · 30 days left · Next: move your DNS\" with **Open checklist**"
        },
        {
          "screen": "Checklist step **Move your DNS**",
          "action": "Click **Download zone file**",
          "expected": "A file of your DNS records downloads. \"Your email records are in Copy exactly. Copy them first.\""
        },
        {
          "screen": "**Where should your DNS go?**",
          "action": "Pick **Back to GoDaddy's DNS** (most people) or **Another DNS host** and enter **New nameserver 1** and **New nameserver 2**",
          "expected": "The steps for that choice show"
        },
        {
          "screen": "**Add your records there**",
          "action": "Add the records from the file at the new DNS, then click **Check my new DNS**",
          "expected": "Each record shows **Found at your new DNS** or **Not found yet**, email first. Registrar DNS that only answers after the switch reads \"GoDaddy's DNS only answers after the switch. We'll check through public DNS straight after you change.\""
        },
        {
          "screen": "**Now change your nameservers to …**",
          "action": "Change the nameservers at your registrar to the ones shown, then click **I've changed them**",
          "expected": "\"Usually under an hour, sometimes up to 48. We'll email you when it's done.\" When done: \"Your DNS is back with you. Your email keeps working.\" The other steps unlock (before that they read \"Opens once your DNS has moved back.\")"
        },
        {
          "screen": "**Download your data**",
          "action": "Click **Download your data**",
          "expected": "Your site's data downloads as a zip, including your DNS records (\"Available until 14 Nov 2026.\")"
        },
        {
          "screen": "**Add-ons**, **Connected services**, **Billing**, **Your site closes**",
          "action": "Read each",
          "expected": "\"Nothing to settle for your add-ons.\", what disconnects on the notice end, your plan's end date and \"Deleted 30 days later\""
        },
        {
          "screen": "The checklist footer, if you change your mind",
          "action": "Click **Stay with CDS**, then **Stay with CDS** in the dialog",
          "expected": "A toast reads \"Your notice is cancelled.\" Everything carries on as before, including your price"
        }
      ]
    },
    "docs/how-to/media-delivery.md": {
      "feature": "Media delivery (public media store)",
      "route": "/_media/<asset-id>/<variant> on a tenant host",
      "summary": "Variants: images w480, w960, w1600, w2560, thumb; video video.mp4, poster.jpg, poster.webp, thumb, captions.vtt; audio audio.mp3.",
      "activate": [
        {
          "screen": "Repo root, file `.env.local`",
          "action": "For the local stand-in, leave `WASABI_MEDIA_BUCKET` unset",
          "expected": "Public media is written to `.storage-public/` at the repo root (or the folder in `CDS_PUBLIC_STORAGE_DIR`, which must differ from `CDS_STORAGE_DIR`). The app serves it at `/_media/...`"
        },
        {
          "screen": "Same file (and the Coolify app's environment)",
          "action": "Set `CDS_MEDIA_TOKEN_SECRET` to 32 or more random characters, for example the output of `openssl rand -hex 32`",
          "expected": "Media on password-protected pages gets signed links. With `CDS_ENV=production` the app refuses protected media until this is set"
        },
        {
          "screen": "Coolify app environment (dev or prod)",
          "action": "To go live on Wasabi, set `WASABI_MEDIA_BUCKET` to a bucket separate from `WASABI_BUCKET` (for example `cds-platform-media`), together with the existing `WASABI_ACCESS_KEY_ID`, `WASABI_SECRET_ACCESS_KEY`, `WASABI_REGION` and `CDS_ENV`, then redeploy",
          "expected": "Public media now lives in its own bucket. A partial setup, the same bucket as `WASABI_BUCKET`, or production Wasabi keys without `WASABI_MEDIA_BUCKET` stops with an error naming the missing or wrong value"
        }
      ],
      "use": [
        {
          "screen": "A published page on a tenant host, for example `https://<tenant-host>/`",
          "action": "Right-click, choose **View Page Source**, search for `_media`",
          "expected": "Every image, video and audio URL starts with `/_media/<asset-id>/`"
        },
        {
          "screen": "Browser address bar",
          "action": "Open one image URL from step 1, then open the browser's developer tools, **Network** tab, and reload",
          "expected": "The image loads. The response shows `Cache-Control: public, max-age=31536000, immutable` and `Content-Type: image/webp` (captions and posters: `max-age=300`)"
        },
        {
          "screen": "Terminal",
          "action": "Run `curl -s -o /dev/null -D - -r 0-99 https://<tenant-host>/_media/<video-asset-id>/video.mp4`",
          "expected": "The first line is `HTTP/1.1 206 Partial Content` (or `HTTP/2 206`) and `Content-Range: bytes 0-99/<size>` is listed. Browsers use this to seek in a video"
        },
        {
          "screen": "A password-protected page on the tenant host",
          "action": "View the page source and copy one `/_media/...` URL",
          "expected": "The URL ends in `?e=<number>&t=<code>`. It works now, answers `Cache-Control: private, max-age=3600`, and returns 404 about an hour later. The same URL without `e` and `t` is 404"
        }
      ]
    },
