    "docs/how-to/reaccept-terms.md": {
      "feature": "Re-accept updated terms",
      "route": "/hub/agreement?mode=reaccept",
      "summary": "When CDS publishes a new version of a policy the owner has already signed, the owner is asked to accept it the next time they open the hub.",
      "activate": [
        {
          "screen": "CDS repo (staff)",
          "action": "Publish a new version of a policy (for example Terms of Service v2, with a `changes` line) and deploy",
          "expected": "Every org that signed version 1 now has an outdated agreement. Orgs that never signed are not affected"
        }
      ],
      "use": [
        {
          "screen": "`/sign-in`",
          "action": "Sign in as the owner of a site that signed version 1",
          "expected": "Instead of the hub, `/hub/agreement?mode=reaccept&next=/hub/...` opens in a focused frame: only the business name and **Sign out** at the top, no sidebar, no menu"
        },
        {
          "screen": "`/hub/agreement?mode=reaccept`",
          "action": "Read the top of the page",
          "expected": "The heading **We've updated our terms**, the intro \"We changed 1 of the policies you signed. Here's what changed. Sign again to keep using your hub. Your site stays live the whole time.\" and a bar reading \"0 of 1 accepted\""
        },
        {
          "screen": "`/hub/agreement?mode=reaccept`, **Terms of Service** card",
          "action": "Read the card",
          "expected": "\"Version 2 · Effective {date} · You signed version 1 on {date}\", then \"**What changed:** {the change line}\", three bullet points and **Read the full text**"
        },
        {
          "screen": "`/hub/agreement?mode=reaccept`",
          "action": "Read the grey box under the card",
          "expected": "\"Still current, no need to sign again: Service Agreement v1 · Acceptable Use Policy v1 · Subscription terms v1 · Data Processing Agreement v1.\""
        },
        {
          "screen": "`/hub/agreement?mode=reaccept`, **Terms of Service** card",
          "action": "Tick \"I have read and agree to the Terms of Service.\"",
          "expected": "The bar reads \"1 of 1 accepted\""
        },
        {
          "screen": "`/hub/agreement?mode=reaccept`, **Sign your agreement**",
          "action": "Tick the electronic signature consent box (it is asked again every time) and type your full legal name",
          "expected": "**Sign and accept** is no longer faded; the line reads \"{Name}, you're signing for {business} on {today}…\""
        },
        {
          "screen": "`/hub/agreement?mode=reaccept`",
          "action": "Click **Sign and accept**",
          "expected": "**Signing…**, then `/hub/agreement/signed/{id}` opens: \"Your agreement is signed\" with **Download your signed copy** and **Continue to your hub**"
        },
        {
          "screen": "`/hub/agreement/signed/{id}`",
          "action": "Click **Continue to your hub**",
          "expected": "The page you were going to before the update opens, with the normal sidebar"
        },
        {
          "screen": "`/hub` (as an admin, before the owner signs)",
          "action": "Sign in as an admin",
          "expected": "The hub opens as usual with the note \"CDS updated its terms. Your site owner needs to accept them…\". Opening `/hub/agreement` shows the cards read-only with \"Only the site owner can sign this agreement.\" and no **Sign and accept** button"
        }
      ]
    },
