    "docs/how-to/review-your-site-before-launch.md": {
      "feature": "Review your site before launch",
      "route": "/hub/review",
      "summary": "Before CDS launches your site, you look over every page on its preview address, confirm your key details, check it on your phone and send a test message.",
      "activate": [
        {
          "screen": "Today (`/hub`), signed in as the **Owner**, once CDS has your site ready for review",
          "action": "Click **Continue review** on the launch review card",
          "expected": "**Review your site** (`/hub/review`) opens with \"0 of 6 done\" and the six items"
        },
        {
          "screen": "The same screen, signed in as an **Admin**",
          "action": "Read the list",
          "expected": "The items show without buttons, and the line reads \"Only the owner can approve the launch.\""
        }
      ],
      "use": [
        {
          "screen": "**Every page looked over**",
          "action": "Click **Review on your preview address**",
          "expected": "Your site opens in a new tab on its preview address with the strip \"Review mode · Page 1 of 7 · Home\" and **Back to your review**; a bar at the bottom shows **Looks good** · **Needs a change** · **Previous page** · **Next page**"
        },
        {
          "screen": "The review bar",
          "action": "Look over the page, then click **Looks good**",
          "expected": "The next unreviewed page opens and the strip reads \"Marked Home as looks good.\" After the last page: \"All pages looked over.\""
        },
        {
          "screen": "The review bar, a page that needs work",
          "action": "Click **Needs a change**, write **Your note** (at least 10 characters, like \"Change the phone number in the footer.\"), click **Send to CDS**",
          "expected": "You return to the page and the strip reads \"Sent. CDS will make the change and tell you.\" **Changes you asked for** counts it"
        },
        {
          "screen": "**Your key details confirmed**",
          "action": "Click **Confirm your details**, check business name, phone, email, address and hours (**Edit** fixes any), then click **Confirm these details**",
          "expected": "A toast reads \"Key details confirmed.\" If your email isn't confirmed yet: \"Confirm your email address first. We sent the link to maria@gmail.com.\""
        },
        {
          "screen": "**Checked on your phone**",
          "action": "Click **Check on your phone** and scan the code with your phone's camera (or **Copy link** and open it on the phone; it works for 60 minutes)",
          "expected": "The site opens in review mode on the phone. Tap **Checked on my phone** on the first page; the strip reads \"Thanks. Phone check done.\" (On a computer you can click **I checked it on my phone**.)"
        },
        {
          "screen": "**Test form received**",
          "action": "Click **Send a test message**, fill in the contact form on the preview and send it",
          "expected": "The site's own thank-you message shows and the strip adds \"Test message sent. It's in your Inbox.\" The item reads \"It's in your Inbox\" with **Open Inbox**, where the message carries a **Test** badge"
        },
        {
          "screen": "**No open change requests**",
          "action": "Wait for CDS to finish any changes (**See your requests** shows them)",
          "expected": "The item reads \"No open change requests\""
        },
        {
          "screen": "**Your site goes live at riverabakery.com.** panel",
          "action": "Click **Ready to launch**",
          "expected": "The button shows **Sending…**, then \"CDS is giving it a final look.\" with \"Usually within 1 business day. We'll email you the moment you're live. You can still edit, but changed pages need another look.\""
        },
        {
          "screen": "The same panel, if you edit a page after sending",
          "action": "Look at the changed page again and mark it **Looks good**",
          "expected": "The warning \"You changed About us after sending. Look at it again so CDS can launch.\" clears"
        }
      ]
    },
